def con_rangos_observados(hojas: list[dict]) -> list[dict]:
    """Copia el catálogo y agrega el mínimo y el máximo vistos en estas hojas."""
    salida = []
    for variable in VARIABLES:
        fila = dict(variable)
        valores = [h.get(variable["nombre"]) for h in hojas if isinstance(h.get(variable["nombre"]), (int, float))]
        if valores:
            fila["rango_observado"] = {"minimo": min(valores), "maximo": max(valores), "n": len(valores)}
            fila["nota_rango"] = "Rango observado en este archivo. No es un límite de operación ni un rango físicamente válido."
        else:
            fila["rango_observado"] = None
            fila["nota_rango"] = None
        salida.append(fila)
    return salida
